using System.Collections.Generic;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(menuName = "Data/Battle/Game States/Default GameState")]
public class GameState : ScriptableObject
{
	[Header("State Variables")]
	[SerializeField]
	private StringEvent OnStateChange;

	[SerializeField]
	private VoidEvent OnStateChangeVoid;

	[SerializeField]
	private VoidEvent OnEndStateEvent;

	[Header("Mouse")]
	[SerializeField]
	private Action[] mouseActions;

	[Header("Joystick")]
	[SerializeField]
	private Action[] joystickActions;

	[SerializeField]
	private Action[] actions;

	public VoidEvent OnStateChangeVoidEvent => OnStateChangeVoid;

	private InputManager inputManager => ReferenceSingleton<InputManager>.Instance;

	public virtual void OnStartState()
	{
		if (inputManager.IsJoystickBeingUsed)
		{
			SetJoystickActions();
		}
		else
		{
			SetMouseActions();
		}
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].OnStartState();
		}
		OnStateChange.Raise(base.name);
		OnStateChangeVoid?.Raise();
	}

	private void SetMouseActions()
	{
		actions = mouseActions;
	}

	private void SetJoystickActions()
	{
		actions = joystickActions;
	}

	public void Execute(float d)
	{
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].Execute(d);
		}
	}

	public virtual void OnEndState()
	{
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].OnEndState();
		}
		OnEndStateEvent?.Raise();
	}

	public virtual void SetTargetOnActions(List<GameObject> actionTargets)
	{
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].SetActionTargets(actionTargets);
		}
	}

	public virtual void SetHighlightTargetOnActions(List<GameObject> actionTargets)
	{
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].SetActionHighlightTargets(actionTargets);
		}
	}
}
